     8	  * { box-sizing: border-box; margin: 0; padding: 0; }
     9	  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: #f5f5f5; display: flex; justify-content: center; align-items: center; min-height: 100vh; }
    10	  .container { background: #fff; border-radius: 12px; box-shadow: 0 2px 16px rgba(0,0,0,0.08); padding: 32px; width: 100%; max-width: 480px; }
    11	  h1 { font-size: 22px; margin-bottom: 8px; color: #1a1a1a; }
