    13	  .progress-step { flex: 1; height: 4px; background: #e0e0e0; border-radius: 2px; transition: background 0.3s; }
    14	  .progress-step.active { background: #2563eb; }
    15	  .step { display: none; }
    16	  .step.active { display: block; }
    17	  label { display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 6px; margin-top: 16px; }
    18	  input, select { width: 100%; padding: 10px 12px; border: 1px solid #d1d5db; border-radius: 8px; font-size: 15px; outline: none; transition: border 0.2s; }
    19	  input:focus, select:focus { border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37,99,235,0.1); }
    20	  .error-msg { color: #dc2626; font-size: 12px; margin-top: 4px; display: none; }
    21	  .error-msg.visible { display: block; }
    22	  .btn-row { display: flex; gap: 12px; margin-top: 24px; }
    23	  .btn-next, .btn-submit { flex: 1; padding: 12px; background: #2563eb; color: #fff; border: none; border-radius: 8px; font-size: 15px; font-weight: 500; cursor: pointer; transition: background 0.2s; }
    24	  .btn-next:hover, .btn-submit:hover { background: #1d4ed8; }
    25	  .btn-back { flex: 1; padding: 12px; background: #f3f4f6; color: #374151; border: 1px solid #d1d5db; border-radius: 8px; font-size: 15px; cursor: pointer; transition: background 0.2s; }
    26	  .btn-back:hover { background: #e5e7eb; }
    27	  .review-item { display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px solid #f0f0f0; }
    28	  .review-label { font-size: 14px; color: #6b7280; }
    29	  .review-value { font-size: 14px; font-weight: 500; color: #1a1a1a; }
