    37	  <div class="container" data-testid="form-container">
    38	    <h1>Create Account</h1>
    39	
    40	    <div class="progress-bar" data-testid="progress-bar">
    41	      <div class="progress-step active" id="prog-1"></div>
    42	      <div class="progress-step" id="prog-2"></div>
    43	      <div class="progress-step" id="prog-3"></div>
    44	    </div>
    45	
    46	    <!-- Step 1: Personal Info -->
    47	    <div class="step active" id="step-1" data-testid="step-1">
    48	      <label for="fullname">Full Name</label>
    49	      <input type="text" id="fullname" name="fullname" placeholder="John Doe" data-testid="fullname">
    50	      <div class="error-msg" id="err-fullname">Full name is required</div>
    51	
    52	      <label for="email">Email Address</label>
    53	      <input type="email" id="email" name="email" placeholder="john@example.com" data-testid="email">
    54	      <div class="error-msg" id="err-email">Please enter a valid email address</div>
    55	
    56	      <label for="phone">Phone Number</label>
    57	      <input type="tel" id="phone" name="phone" placeholder="+1 555-123-4567" data-testid="phone">
    58	      <div class="error-msg" id="err-phone">Phone number is required</div>
    59	
    60	      <div class="btn-row">
    61	        <button class="btn-next" onclick="goToStep(2)" data-testid="next-1">Next</button>
    62	      </div>
    63	    </div>
    64	
    65	    <!-- Step 2: Address -->
    66	    <div class="step" id="step-2" data-testid="step-2">
    67	      <label for="street">Street Address</label>
    68	      <input type="text" id="street" name="street" placeholder="123 Main St" data-testid="street">
    69	      <div class="error-msg" id="err-street">Street address is required</div>
    70	
    71	      <label for="city">City</label>
    72	      <input type="text" id="city" name="city" placeholder="San Francisco" data-testid="city">
    73	      <div class="error-msg" id="err-city">City is required</div>
    74	
    75	      <label for="state">State</label>
    76	      <select id="state" name="state" data-testid="state">
    77	        <option value="">Select State</option>
    78	        <option value="CA">California</option>
    79	        <option value="NY">New York</option>
    80	        <option value="TX">Texas</option>
    81	        <option value="FL">Florida</option>
    82	        <option value="WA">Washington</option>
    83	      </select>
    84	      <div class="error-msg" id="err-state">Please select a state</div>
