   118	  <script>
   119	    let currentStep = 1;
   120	
   121	    function validateStep1() {
   122	      let valid = true;
   123	      const fullname = document.getElementById('fullname').value.trim();
   124	      const email = document.getElementById('email').value.trim();
   125	      const phone = document.getElementById('phone').value.trim();
   126	
   127	      if (!fullname) { document.getElementById('err-fullname').classList.add('visible'); valid = false; }
   128	      else { document.getElementById('err-fullname').classList.remove('visible'); }
   129	
   130	      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
   131	      if (!emailRegex.test(email)) { document.getElementById('err-email').classList.add('visible'); valid = false; }
   132	      else { document.getElementById('err-email').classList.remove('visible'); }
   133	
   134	      if (!phone) { document.getElementById('err-phone').classList.add('visible'); valid = false; }
   135	      else { document.getElementById('err-phone').classList.remove('visible'); }
   136	
   137	      return valid;
   138	    }
   139	
   140	    function validateStep2() {
   141	      let valid = true;
   142	      const street = document.getElementById('street').value.trim();
   143	      const city = document.getElementById('city').value.trim();
   144	      const state = document.getElementById('state').value;
   145	      const zip = document.getElementById('zip').value.trim();
   146	
   147	      if (!street) { document.getElementById('err-street').classList.add('visible'); valid = false; }
   148	      else { document.getElementById('err-street').classList.remove('visible'); }
   149	
   150	      if (!city) { document.getElementById('err-city').classList.add('visible'); valid = false; }
   151	      else { document.getElementById('err-city').classList.remove('visible'); }
   152	
   153	      if (!state) { document.getElementById('err-state').classList.add('visible'); valid = false; }
   154	      else { document.getElementById('err-state').classList.remove('visible'); }
   155	
   156	      const zipRegex = /^\d{5}$/;
   157	      if (!zipRegex.test(zip)) { document.getElementById('err-zip').classList.add('visible'); valid = false; }
   158	      else { document.getElementById('err-zip').classList.remove('visible'); }
   159	
   160	      return valid;
   161	    }
