   163	    function populateReview() {
   164	      document.getElementById('review-fullname').textContent = document.getElementById('fullname').value;
   165	      document.getElementById('review-email').textContent = document.getElementById('email').value;
   166	      document.getElementById('review-phone').textContent = document.getElementById('phone').value;
   167	      const street = document.getElementById('street').value;
   168	      const city = document.getElementById('city').value;
   169	      const state = document.getElementById('state').value;
   170	      const zip = document.getElementById('zip').value;
   171	      document.getElementById('review-address').textContent = `${street}, ${city}, ${state} ${zip}`;
   172	    }
   173	
   174	    function goToStep(step) {
   175	      if (step === 2 && currentStep === 1 && !validateStep1()) return;
   176	      if (step === 3 && currentStep === 2 && !validateStep2()) return;
   177	      if (step === 3) populateReview();
   178	
   179	      document.getElementById(`step-${currentStep}`).classList.remove('active');
   180	      document.getElementById(`step-${step}`).classList.add('active');
   181	
   182	      for (let i = 1; i <= 3; i++) {
   183	        document.getElementById(`prog-${i}`).classList.toggle('active', i <= step);
   184	      }
   185	
   186	      currentStep = step;
   187	    }
   188	
   189	    function submitForm() {
   190	      const id = 'REG-' + Math.random().toString(36).substring(2, 10).toUpperCase();
   191	      document.getElementById('submission-id').textContent = id;
   192	      document.getElementById(`step-${currentStep}`).classList.remove('active');
   193	      document.getElementById('success-panel').style.display = 'block';
   194	    }
   195	  </script>
   196	</body>
   197	</html>

